FROM ((
SELECT F0_1.L_ORDERKEY AS L_ORDERKEY, F0_1.L_PARTKEY AS L_PARTKEY, F0_1.L_SUPPKEY AS L_SUPPKEY, F0_1.L_LINENUMBER AS L_LINENUMBER, F0_1.L_QUANTITY AS L_QUANTITY, F0_1.L_EXTENDEDPRICE AS L_EXTENDEDPRICE, F0_1.L_DISCOUNT AS L_DISCOUNT, F0_1.L_TAX AS L_TAX, F0_1.L_RETURNFLAG AS L_RETURNFLAG, F0_1.L_LINESTATUS AS L_LINESTATUS, F0_1.L_SHIPDATE AS L_SHIPDATE, F0_1.L_COMMITDATE AS L_COMMITDATE, F0_1.L_RECEIPTDATE AS L_RECEIPTDATE, F0_1.L_SHIPINSTRUCT AS L_SHIPINSTRUCT, F0_1.L_SHIPMODE AS L_SHIPMODE, F0_1.L_COMMENT AS L_COMMENT, F0_1.PROV_LINEITEM_L__ORDERKEY AS PROV_LINEITEM_L__ORDERKEY, F0_1.PROV_LINEITEM_L__LINENUMBER AS PROV_LINEITEM_L__LINENUMBER, F0_1._RESULT_TID AS _RESULT_TID, F0_1._SETPROV_DUP_COUNT AS _SETPROV_DUP_COUNT
FROM (
SELECT F0_1.L_ORDERKEY AS L_ORDERKEY, F0_1.L_PARTKEY AS L_PARTKEY, F0_1.L_SUPPKEY AS L_SUPPKEY, F0_1.L_LINENUMBER AS L_LINENUMBER, F0_1.L_QUANTITY AS L_QUANTITY, F0_1.L_EXTENDEDPRICE AS L_EXTENDEDPRICE, F0_1.L_DISCOUNT AS L_DISCOUNT, F0_1.L_TAX AS L_TAX, F0_1.L_RETURNFLAG AS L_RETURNFLAG, F0_1.L_LINESTATUS AS L_LINESTATUS, F0_1.L_SHIPDATE AS L_SHIPDATE, F0_1.L_COMMITDATE AS L_COMMITDATE, F0_1.L_RECEIPTDATE AS L_RECEIPTDATE, F0_1.L_SHIPINSTRUCT AS L_SHIPINSTRUCT, F0_1.L_SHIPMODE AS L_SHIPMODE, F0_1.L_COMMENT AS L_COMMENT, F0_1.L_ORDERKEY AS PROV_LINEITEM_L__ORDERKEY, F0_1.L_LINENUMBER AS PROV_LINEITEM_L__LINENUMBER, F0_1.rowid AS _RESULT_TID, 1 AS _SETPROV_DUP_COUNT
FROM LINEITEM F0_1) F0_1
WHERE ((F0_1.L_ORDERKEY = F0_0.O_ORDERKEY) AND (F0_1.L_COMMITDATE < F0_1.L_RECEIPTDATE)) UNION ALL (SELECT NULL AS L_ORDERKEY, NULL AS L_PARTKEY, NULL AS L_SUPPKEY, NULL AS L_LINENUMBER, NULL AS L_QUANTITY, NULL AS L_EXTENDEDPRICE, NULL AS L_DISCOUNT, NULL AS L_TAX, NULL AS L_RETURNFLAG, NULL AS L_LINESTATUS, NULL AS L_SHIPDATE, NULL AS L_COMMITDATE, NULL AS L_RECEIPTDATE, NULL AS L_SHIPINSTRUCT, NULL AS L_SHIPMODE, NULL AS L_COMMENT, NULL AS PROV_LINEITEM_L__ORDERKEY, NULL AS PROV_LINEITEM_L__LINENUMBER, -1 AS _RESULT_TID, NULL AS _SETPROV_DUP_COUNT))) F0_1) F0_1
WHERE ((F0_1."AGGR_0" = 0) OR (F0_1._RESULT_TID <> -1))) F0_1) F0_1) F1_0),
temp_view_1 AS (
SELECT /*+ materialize */ F0_0."AGGR_0" AS "AGGR_0", F0_0."AGG_GB_ARG1" AS "GROUP_0", F0_0.PROV_ORDERS_O__ORDERKEY AS PROV_ORDERS_O__ORDERKEY, F0_0.PROV_LINEITEM_L__ORDERKEY AS PROV_LINEITEM_L__ORDERKEY, F0_0.PROV_LINEITEM_L__LINENUMBER AS PROV_LINEITEM_L__LINENUMBER, DENSE_RANK() OVER ( ORDER BY F0_0."AGG_GB_ARG1") AS _RESULT_TID, ROW_NUMBER() OVER (PARTITION BY F0_0."AGG_GB_ARG1" ORDER BY F0_0."AGG_GB_ARG1") AS _SETPROV_DUP_COUNT
FROM (
