FROM (
SELECT F0_0.O_ORDERKEY AS O_ORDERKEY, F0_0.O_CUSTKEY AS O_CUSTKEY, F0_0.O_ORDERSTATUS AS O_ORDERSTATUS, F0_0.O_TOTALPRICE AS O_TOTALPRICE, F0_0.O_ORDERDATE AS O_ORDERDATE, F0_0.O_ORDERPRIORITY AS O_ORDERPRIORITY, F0_0.O_CLERK AS O_CLERK, F0_0.O_SHIPPRIORITY AS O_SHIPPRIORITY, F0_0.O_COMMENT AS O_COMMENT, F0_0."NESTING_EVAL_1" AS "NESTING_EVAL_1", F0_0.PROV_ORDERS_O__ORDERKEY AS PROV_ORDERS_O__ORDERKEY, F0_0.PROV_LINEITEM_L__ORDERKEY AS PROV_LINEITEM_L__ORDERKEY, F0_0.PROV_LINEITEM_L__LINENUMBER AS PROV_LINEITEM_L__LINENUMBER, F0_0._RESULT_TID AS _RESULT_TID, F0_0._SETPROV_DUP_COUNT AS _SETPROV_DUP_COUNT
