FROM (SELECT * FROM temp_view_1) F0_0
ORDER BY O_ORDERPRIORITY ASC NULLS LAST) F0_0)
SELECT F0_0.PROV_ORDERS_O__ORDERKEY AS PROV_ORDERS_O__ORDERKEY, F0_0.PROV_LINEITEM_L__LINENUMBER AS PROV_LINEITEM_L__LINENUMBER, F0_0.PROV_LINEITEM_L__ORDERKEY AS PROV_LINEITEM_L__ORDERKEY
